prologue:
enum { PlayerMaxHooks = 16 };
static AmodPlayerUpdateHandler g_player_drive_fns[PlayerMaxHooks];
static int g_player_drive_cnt = 0;
static int g_player_drive_mode = AMOD_PLAYER_DRIVER_BOTH;
static AmodPlayerStateHandler g_player_state_fns[4][PlayerMaxHooks];
static int g_player_state_cnt[4];
static AmodPlayerDeathHandler g_player_death_fns[PlayerMaxHooks];
static int g_player_death_cnt = 0;
static AmodPlayerMoveHandler g_player_move_fns[PlayerMaxHooks];
static int g_player_move_cnt = 0;
static AmodPlayerMove* g_player_move_ptr = 0;
static AmodPlayerMove g_player_last_move;
static AmodPlayerEventInfo g_player_last_ev;
static AmodPlayerDeathInfo g_player_last_death;
static AmodPlayerFrame g_player_last_frame;
static int g_player_last_exit = 0;

static MOD_UNUSED int player_is_here(void) {
    return (API->player != 0 && API->player->IsHere != 0) ? API->player->IsHere(SELF) : 0;
}

static MOD_UNUSED int player_read(AmodPlayer* out) {
    if (API->player == 0 || API->player->Get == 0) return 0;
    memset(out, 0, sizeof *out);
    out->structSize = sizeof *out;
    return API->player->Get(SELF, out);
}

static MOD_UNUSED float player_position(int axis) {
    AmodPlayer p;
    if (axis < 0 || axis > 2 || player_read(&p) == 0) return 0.0f;
    return p.position[axis];
}

static MOD_UNUSED float player_num(int which) {
    AmodPlayer p;
    if (player_read(&p) == 0) return 0.0f;
    if (which >= 0 && which < 3) return p.position[which];
    if (which >= 3 && which < 6) return p.previousPosition[which - 3];
    if (which == 6) return p.facing;
    if (which == 7) return p.fallSpeed;
    return 0.0f;
}

static MOD_UNUSED int player_int(int which) {
    AmodPlayer p;
    if (player_read(&p) == 0) return which == 0 ? -1 : 0;
    if (which == 0) return p.entity;
    if (which == 1) return p.state;
    if (which == 2) return p.subState;
    return 0;
}

static MOD_UNUSED int player_flag(int which) {
    AmodPlayer p;
    if (player_read(&p) == 0) return 0;
    if (which == 0) return p.isDead;
    if (which == 1) return p.isCrashed;
    if (which == 2) return p.isOnFire;
    if (which == 3) return p.isShocked;
    return 0;
}

static MOD_UNUSED int player_facing_dir(void) {
    return player_num(6) < 0.0f ? 1 : 0;
}

static MOD_UNUSED void player_set_pos(float x, float y, float z, int onlyCurrent) {
    float pos[3];
    if (API->player == 0) return;
    pos[0] = x; pos[1] = y; pos[2] = z;
    if (onlyCurrent != 0) {
        if (API->player->SetPositionOnly != 0) API->player->SetPositionOnly(SELF, pos);
    } else {
        if (API->player->SetPosition != 0) API->player->SetPosition(SELF, pos);
    }
}

static MOD_UNUSED void player_set_facing(float facing) {
    if (API->player != 0 && API->player->SetFacing != 0) API->player->SetFacing(SELF, facing);
}

static MOD_UNUSED int player_collides(void) {
    return (API->player != 0 && API->player->Collides != 0) ? API->player->Collides(SELF) : 1;
}

static MOD_UNUSED void player_set_collides(int collides) {
    if (API->player != 0 && API->player->SetCollides != 0) API->player->SetCollides(SELF, collides != 0 ? 1 : 0);
}

static MOD_UNUSED void player_toggle_collides(void) {
    player_set_collides(player_collides() != 0 ? 0 : 1);
}

static MOD_UNUSED void player_kill(int crashed) {
    if (API->player != 0 && API->player->Kill != 0) API->player->Kill(SELF, crashed != 0 ? 1 : 0);
}

static MOD_UNUSED void player_burn(void) {
    if (API->player != 0 && API->player->Burn != 0) API->player->Burn(SELF);
}

static MOD_UNUSED int player_lives(void) {
    return (API->player != 0 && API->player->GetLives != 0) ? API->player->GetLives(SELF) : 0;
}

static MOD_UNUSED void player_set_lives(int lives) {
    if (API->player != 0 && API->player->SetLives != 0) API->player->SetLives(SELF, lives);
}

static MOD_UNUSED void player_add_lives(int delta) {
    int v = player_lives() + delta;
    if (v < 0) v = 0;
    player_set_lives(v);
}

static MOD_UNUSED int player_score(void) {
    return (API->player != 0 && API->player->GetScore != 0) ? API->player->GetScore(SELF) : 0;
}

static MOD_UNUSED void player_add_score(int points) {
    if (API->player != 0 && API->player->AddScore != 0) API->player->AddScore(SELF, points, 0);
}

static MOD_UNUSED void player_add_score_at(int points, float x, float y, float z) {
    float pos[3];
    if (API->player == 0 || API->player->AddScore == 0) return;
    pos[0] = x; pos[1] = y; pos[2] = z;
    API->player->AddScore(SELF, points, pos);
}

static MOD_UNUSED void player_set_score(int score) {
    if (API->player != 0 && API->player->SetScore != 0) API->player->SetScore(SELF, score);
}

static MOD_UNUSED void player_cancel(AmodToken tok) {
    if (tok == 0 || API->player == 0) return;
    if (API->player->Cancel != 0) API->player->Cancel(SELF, tok);
    else if (API->player->RemoveEventHandler != 0) API->player->RemoveEventHandler(SELF, tok);
}

static MOD_UNUSED void __cdecl player_event_relay(const AmodPlayerEventInfo* info, void* user) {
    if (info != 0) g_player_last_ev = *info;
    if (user != 0) ((AmodPlayerEventHandler)user)(info, 0);
}

static MOD_UNUSED int player_event_int(int which) {
    switch (which) {
        case 0: return (int)g_player_last_ev.event;
        case 1: return g_player_last_ev.lives;
        case 2: return g_player_last_ev.wasLives;
        case 3: return g_player_last_ev.score;
        case 4: return g_player_last_ev.wasScore;
        case 5: return g_player_last_ev.crashed;
        default: return 0;
    }
}

static MOD_UNUSED void __cdecl player_drive_mux(const AmodPlayerFrame* pframe, void* user) {
    int i;
    (void)user;
    if (pframe != 0) g_player_last_frame = *pframe;
    for (i = 0; i < g_player_drive_cnt; ++i) {
        if (g_player_drive_fns[i] != 0) g_player_drive_fns[i](pframe, 0);
    }
}

static MOD_UNUSED void player_add_drive(int mode, AmodPlayerUpdateHandler fn) {
    if (fn != 0 && g_player_drive_cnt < PlayerMaxHooks) {
        g_player_drive_fns[g_player_drive_cnt++] = fn;
    }
    g_player_drive_mode = mode;
    if (API->player != 0 && API->player->Drive != 0) {
        API->player->Drive(SELF, (AmodPlayerDriver)mode, player_drive_mux, 0);
    }
}

static MOD_UNUSED void player_set_driver(int mode) {
    if (API->player == 0) return;
    if (mode == AMOD_PLAYER_DRIVER_GAME) {
        if (API->player->Release != 0) API->player->Release(SELF);
        return;
    }
    if (mode == AMOD_PLAYER_DRIVER_NOBODY) {
        if (API->player->Drive != 0) API->player->Drive(SELF, AMOD_PLAYER_DRIVER_NOBODY, 0, 0);
        return;
    }
    g_player_drive_mode = mode;
    if (API->player->Drive != 0) {
        API->player->Drive(SELF, (AmodPlayerDriver)mode, player_drive_mux, 0);
    }
}

static MOD_UNUSED void player_release_driver(void) {
    if (API->player != 0 && API->player->Release != 0) API->player->Release(SELF);
}

static MOD_UNUSED int player_driver(void) {
    return (API->player != 0 && API->player->Driver != 0) ? (int)API->player->Driver(SELF) : AMOD_PLAYER_DRIVER_GAME;
}

static MOD_UNUSED void player_step(int dirX, int dirY, int jump, float delta) {
    if (API->player == 0 || API->player->Step == 0) return;
    g_player_last_exit = API->player->Step(SELF, dirX, dirY, jump != 0 ? 1 : 0, delta);
}

static MOD_UNUSED int player_last_step_exit(void) {
    return g_player_last_exit;
}

static MOD_UNUSED int player_read_place(AmodPlayerPlace* out) {
    if (API->player == 0 || API->player->GetPlace == 0) return 0;
    memset(out, 0, sizeof *out);
    out->structSize = sizeof *out;
    return API->player->GetPlace(SELF, out);
}

static MOD_UNUSED int player_place_int(int which) {
    AmodPlayerPlace pl;
    if (player_read_place(&pl) == 0) return 0;
    switch (which) {
        case 0: return pl.column;
        case 1: return pl.row;
        case 2: return pl.atColumn;
        case 3: return pl.atRow;
        case 4: return pl.columns;
        case 5: return pl.rows;
        default: return 0;
    }
}

static MOD_UNUSED int player_place_cell(int col, int row) {
    AmodPlayerPlace pl;
    if (player_read_place(&pl) == 0) return 0;
    if (col < 0 || col >= pl.columns || row < 0 || row >= pl.rows) return 0;
    return (int)(unsigned char)pl.cells[row * pl.columns + col];
}

static MOD_UNUSED int player_place_offset_code(int dc, int dr) {
    AmodPlayerPlace pl;
    int c, r;
    if (player_read_place(&pl) == 0) return 0;
    c = pl.atColumn + dc;
    r = pl.atRow + dr;
    if (c < 0 || c >= pl.columns || r < 0 || r >= pl.rows) return 0;
    return (int)(unsigned char)pl.cells[r * pl.columns + c];
}

static MOD_UNUSED const char* player_place_here_text(void) {
    static char buf[2];
    int ch = player_place_offset_code(0, 0);
    buf[0] = ch > 0 ? (char)ch : ' ';
    buf[1] = 0;
    return buf;
}

static MOD_UNUSED int player_ask(int question) {
    return (API->player != 0 && API->player->Ask != 0) ? API->player->Ask(SELF, (AmodPlayerPlaceAsk)question) : -1;
}

static MOD_UNUSED int player_state_run(int st, const AmodPlayerFrame* pframe) {
    int i, veto = 0;
    if (pframe != 0) g_player_last_frame = *pframe;
    if (st < 0 || st >= 4) return 0;
    for (i = 0; i < g_player_state_cnt[st]; ++i) {
        if (g_player_state_fns[st][i] != 0 && g_player_state_fns[st][i](pframe, 0) != 0) veto = 1;
    }
    return veto;
}

static MOD_UNUSED int __cdecl player_state_mux_0(const AmodPlayerFrame* pframe, void* user) { (void)user; return player_state_run(0, pframe); }
static MOD_UNUSED int __cdecl player_state_mux_1(const AmodPlayerFrame* pframe, void* user) { (void)user; return player_state_run(1, pframe); }
static MOD_UNUSED int __cdecl player_state_mux_2(const AmodPlayerFrame* pframe, void* user) { (void)user; return player_state_run(2, pframe); }
static MOD_UNUSED int __cdecl player_state_mux_3(const AmodPlayerFrame* pframe, void* user) { (void)user; return player_state_run(3, pframe); }

static MOD_UNUSED AmodPlayerStateHandler player_state_mux_of(int st) {
    if (st == 0) return player_state_mux_0;
    if (st == 1) return player_state_mux_1;
    if (st == 2) return player_state_mux_2;
    return player_state_mux_3;
}

static MOD_UNUSED void player_add_state_hook(int st, AmodPlayerStateHandler fn) {
    if (st < 0 || st >= 4) return;
    if (fn != 0 && g_player_state_cnt[st] < PlayerMaxHooks) {
        g_player_state_fns[st][g_player_state_cnt[st]++] = fn;
    }
    if (API->player != 0 && API->player->SetStateHandler != 0) {
        API->player->SetStateHandler(SELF, st, player_state_mux_of(st), 0);
    }
}

static MOD_UNUSED void player_clear_state_hook(int st) {
    if (API->player != 0 && API->player->ClearStateHandler != 0) API->player->ClearStateHandler(SELF, st);
}

static MOD_UNUSED int __cdecl player_death_mux(const AmodPlayerDeathInfo* dinfo, void* user) {
    int i, veto = 0;
    (void)user;
    if (dinfo != 0) g_player_last_death = *dinfo;
    for (i = 0; i < g_player_death_cnt; ++i) {
        if (g_player_death_fns[i] != 0 && g_player_death_fns[i](dinfo, 0) != 0) veto = 1;
    }
    return veto;
}

static MOD_UNUSED void player_add_death_hook(AmodPlayerDeathHandler fn) {
    if (fn != 0 && g_player_death_cnt < PlayerMaxHooks) {
        g_player_death_fns[g_player_death_cnt++] = fn;
    }
    if (API->player != 0 && API->player->SetDeathHandler != 0) {
        API->player->SetDeathHandler(SELF, player_death_mux, 0);
    }
}

static MOD_UNUSED void player_clear_death_hook(void) {
    if (API->player != 0 && API->player->ClearDeathHandler != 0) API->player->ClearDeathHandler(SELF);
}

static MOD_UNUSED void __cdecl player_move_mux(AmodPlayerMove* move, void* user) {
    int i;
    (void)user;
    g_player_move_ptr = move;
    if (move != 0) g_player_last_move = *move;
    for (i = 0; i < g_player_move_cnt; ++i) {
        if (g_player_move_fns[i] != 0) g_player_move_fns[i](move, 0);
    }
    if (move != 0) g_player_last_move = *move;
    g_player_move_ptr = 0;
}

static MOD_UNUSED void player_add_move_hook(AmodPlayerMoveHandler fn) {
    if (fn != 0 && g_player_move_cnt < PlayerMaxHooks) {
        g_player_move_fns[g_player_move_cnt++] = fn;
    }
    if (API->player != 0 && API->player->SetMoveHandler != 0) {
        API->player->SetMoveHandler(SELF, player_move_mux, 0);
    }
}

static MOD_UNUSED void player_clear_move_hook(void) {
    if (API->player != 0 && API->player->ClearMoveHandler != 0) API->player->ClearMoveHandler(SELF);
}

static MOD_UNUSED void player_set_move_intent(int dirX, int dirY) {
    if (g_player_move_ptr == 0) return;
    if (dirX >= -1 && dirX <= 1) g_player_move_ptr->dirX = dirX;
    if (dirY >= -1 && dirY <= 1) g_player_move_ptr->dirY = dirY;
    g_player_last_move = *g_player_move_ptr;
}

static MOD_UNUSED void player_rearm_hooks(int which) {
    int st;
    if (API->player == 0) return;
    if ((which == 0 || which == 1) && g_player_move_cnt > 0 && API->player->SetMoveHandler != 0) {
        API->player->SetMoveHandler(SELF, player_move_mux, 0);
    }
    if ((which == 0 || which == 2) && g_player_death_cnt > 0 && API->player->SetDeathHandler != 0) {
        API->player->SetDeathHandler(SELF, player_death_mux, 0);
    }
    if ((which == 0 || which == 3) && API->player->SetStateHandler != 0) {
        for (st = 0; st < 4; ++st) {
            if (g_player_state_cnt[st] > 0) API->player->SetStateHandler(SELF, st, player_state_mux_of(st), 0);
        }
    }
}

static MOD_UNUSED int player_death_int(int which) {
    return which == 0 ? g_player_last_death.kind : g_player_last_death.lives;
}

static MOD_UNUSED float player_death_pos(int axis) {
    return (axis >= 0 && axis < 3) ? g_player_last_death.position[axis] : 0.0f;
}

static MOD_UNUSED float player_frame_num(int which) {
    if (which == 0) return g_player_last_frame.delta;
    if (which >= 1 && which <= 3) return g_player_last_frame.position[which - 1];
    if (which == 4) return g_player_last_frame.fallSpeed;
    if (which == 5) return g_player_last_frame.facing;
    return 0.0f;
}

static MOD_UNUSED int player_frame_int(int which) {
    if (which == 0) return g_player_last_frame.state;
    if (which == 1) return g_player_last_frame.subState;
    return g_player_last_frame.isDead;
}

static MOD_UNUSED int player_move_dir(int isY) {
    if (g_player_move_ptr != 0) return isY ? g_player_move_ptr->dirY : g_player_move_ptr->dirX;
    return isY ? g_player_last_move.dirY : g_player_last_move.dirX;
}
